package com.greatleyposhley.professy.components;
import com.greatleyposhley.professy.entities.UserAccount;import com.greatleyposhley.professy.repositories.UserAccountRepository;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.context.RequestAttributeSecurityContextRepository;import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class JwtAsyncContextTest {
 @Test void authenticatedIdentitySurvivesAnAsyncDispatch()throws Exception{String secret="test-only-key-with-at-least-thirty-two-characters";var users=mock(UserAccountRepository.class);var user=new UserAccount();user.setId(4L);user.setOrgId(7L);when(users.findByEmail("member@example.test")).thenReturn(Optional.of(user));String token=Jwts.builder().subject("member@example.test").claim("credentialVersion",0).signWith(Keys.hmacShaKeyFor(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8))).compact();var request=new MockHttpServletRequest("GET","/api/workspace/settings/events");request.setServletPath("/api/workspace/settings/events");request.addHeader("Authorization","Bearer "+token);var response=new MockHttpServletResponse();try{new JwtAuthenticationFilter(secret,users).doFilter(request,response,(req,res)->assertEquals("member@example.test",SecurityContextHolder.getContext().getAuthentication().getName()));SecurityContextHolder.clearContext();request.setDispatcherType(jakarta.servlet.DispatcherType.ASYNC);assertEquals("member@example.test",new RequestAttributeSecurityContextRepository().loadDeferredContext(request).get().getAuthentication().getName());}finally{SecurityContextHolder.clearContext();}}
}
